#ifndef _GIFIMAGE_H
#define _GIFIMAGE_H

#include "Arduino.h"
#include "wled.h"

#ifdef WLED_ENABLE_GIF

#include "GifDecoder.h"

/* Maximum size of the decoded RGB frame buffer in bytes.
 * Matches the BMP path's buffer limit (BUF_SIZE in bmpimage.cpp). */
#define GIF_BUF_SIZE 64000

// AI: below section was generated by an AI
/*
 * This class decodes a GIF file from the filesystem into a packed RGB frame
 * buffer (width*height triplets, no row padding), one frame at a time.
 *
 * It wraps the same decoder libraries that WLED's core "Image" effect uses
 * (see wled00/image_loader.cpp):
 * https://github.com/bitbank2/AnimatedGIF
 * https://github.com/Aircoookie/GifDecoder
 *
 * The decoder is streaming and callback-based: decodeFrame() decodes one whole
 * frame (blocking for a few milliseconds) and delivers its pixels through a
 * draw-pixel callback. There is no random access, so each frame is accumulated
 * in a frame buffer and the POV effect reads columns from it. Like the core
 * effect, frames are composited onto the previous content (the buffer is only
 * cleared when a new file is loaded), which is how delta-encoded animated GIFs
 * are rendered.
 *
 * A separate GifDecoder template instantiation (useMalloc=false) is used so the
 * decoder's static callback pointers do not clash with the core effect's
 * GifDecoder<320,320,12,true>.
 */
class GIFimage {
    public:
        GIFimage() {}
        ~GIFimage() { unload(); }

        int  width()     { return _width;  }
        int  height()    { return _height; }
        bool isLoaded()  { return _loaded; }
        char * getFilename() { return filename; }

        /* Opens the file and prepares the decoder (header parsed, frame buffer
         * allocated). The first frame is not decoded yet; call decodeFrame().
         * On failure the filename is cleared and no resources are kept.
         */
        bool init(const char* fn);

        /* Decodes the next frame into the frame buffer, looping back to the
         * first frame after the last one. Returns false on decode errors
         * (the image becomes unloaded and can be retried via init()).
         * Single-frame GIFs are decoded only once; later calls are no-ops
         * because the frame buffer already holds the image.
         */
        bool decodeFrame();

        /* Releases the frame buffer, the decoder and the file handle */
        void unload();

        /* Returns a pointer to the RGB triplet of the first pixel (col, 0) of a
         * column, or nullptr when the image is not loaded or the column is out
         * of range. Pixels down the column are spaced width()*3 bytes apart
         * (packed RGB, no padding).
         */
        const uint8_t * columnPtr(uint16_t col) const;

    private:
        GifDecoder<320, 320, 12, false> decoder;
        char filename[WLED_MAX_SEGNAME_LEN+2] = ""; // "/" + segment name + '\0'
        int _width = 0;
        int _height = 0;
        bool _loaded = false;
        bool _singleFrame = false; // true once a single-frame GIF has been decoded
};
// AI: end

#endif // WLED_ENABLE_GIF
#endif // _GIFIMAGE_H
